#include <stdio.h>
#include <math.h>
#include <string.h>

#define first 10

void main()
{
    int i;
    int j,n;

    for(i = 1; i<= first; i++)
        for(j = 0; j<= first; j++)
            if((n = (i + j) % first)==0 && (i % 10 == j % 10))
                printf("%s\n",n);

    return;
}
